/**
 * Contact Inbox – Frontend JS v5.4
 * Real-time validation with character counters and file validation
 */
document.addEventListener('DOMContentLoaded', () => {
      // Allowed file extensions and max file size from backend config or defaults
      const allowedExtKeys = (window.cinFormConfig && window.cinFormConfig.allowedFileTypes)
        ? window.cinFormConfig.allowedFileTypes.split(',').map(e => e.trim().toLowerCase())
        : ['jpg', 'png', 'gif', 'pdf', 'doc', 'docx'];
      const maxFileSize = (window.cinFormConfig && window.cinFormConfig.maxFileSize)
        ? parseInt(window.cinFormConfig.maxFileSize, 10)
        : 2;

      // Define validateFieldRealTime before use
      const validateFieldRealTime = (input, type = 'text', maxLength = null) => {
        const value = input.value.trim();
        if (!value) {
          showError(input, '');
          return;
        }
        let error = '';
        if (maxLength && value.length > maxLength) {
          error = `Maximum ${maxLength} characters allowed.`;
        } else if (type === 'email' && value.length > 0) {
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value)) {
            error = 'Invalid email format.';
          }
        } else if (type === 'phone' && value.length > 0) {
          const phonePattern = /^[0-9+\-\s()]{7,20}$/;
          if (!phonePattern.test(value)) {
            error = 'Invalid phone format (7-20 characters, numbers, +, -, spaces, parentheses).';
          }
        }
        showError(input, error);
      };

      // Define validateTextField before use
      const validateTextField = (input, type = 'text', maxLength = null, minWords = 1) => {
        const value = input.value.trim();
        showError(input, '');
        if (!value) {
          showError(input, 'This field is required.');
          return false;
        }
        if (maxLength && value.length > maxLength) {
          showError(input, `Maximum ${maxLength} characters allowed.`);
          return false;
        }
        if (type === 'text') {
          if (/^\d+$/.test(value)) {
            showError(input, 'Only digits are not allowed. Please enter words.');
            return false;
          }
          if (!/[A-Za-z]/.test(value)) {
            showError(input, 'Input must contain letters.');
            return false;
          }
          const words = value.split(/\s+/).filter(w => w.length >= 2);
          if (words.length < minWords) {
            showError(input, `Please enter at least ${minWords} words.`);
            return false;
          }
        }
        if (type === 'email') {
          const emails = value.split(',').map(e => e.trim());
          const invalid = emails.find(e => !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e) || e.length > 254);
          if (invalid) {
            showError(input, `Invalid email address: ${invalid}`);
            return false;
          }
        }
        if (type === 'phone') {
          const phonePattern = /^[0-9+\-\s()]{7,20}$/;
          if (!phonePattern.test(value)) {
            showError(input, 'Invalid phone number format.');
            return false;
          }
        }
        return true;
      };
    // Define updateCharCounter before use
    const updateCharCounter = (input) => {
      const fieldMeta = input.parentNode.querySelector('.cin-field-meta');
      if (!fieldMeta) return;
      const counterEl = fieldMeta.querySelector('.cin-char-counter');
      if (counterEl) {
        const maxLength = input.maxLength || input.getAttribute('data-max') || 0;
        const currentLength = input.value.length;
        counterEl.textContent = `${currentLength}/${maxLength}`;
        if (maxLength > 0) {
          const percentUsed = (currentLength / maxLength) * 100;
          if (percentUsed >= 90) {
            counterEl.style.color = '#d63638';
            counterEl.style.fontWeight = 'bold';
          } else if (percentUsed >= 80) {
            counterEl.style.color = '#ff8800';
            counterEl.style.fontWeight = 'normal';
          } else {
            counterEl.style.color = 'inherit';
            counterEl.style.fontWeight = 'normal';
          }
        }
      }
    };
  const form = document.querySelector('#contactin-form');
  const responseEl = document.querySelector('.cin-response');
  if (!form || !responseEl) return;
  // Define all field inputs before use
  const nameInput    = form.querySelector('input[name="name"]');
  const subjectInput = form.querySelector('input[name="subject"]');
  const messageInput = form.querySelector('textarea[name="message"]');
  const emailInput   = form.querySelector('input[name="email"]');
  const phoneInput   = form.querySelector('input[name="phone"]');
  const fileInput    = form.querySelector('input[type="file"][name="attachment"]');
  const submitBtn = form.querySelector('.cin-submit-btn');

  // Ensure recaptcha config is defined
  const recaptcha = window.contactin?.recaptcha || { enabled: false, site_key: '' };

  form.addEventListener('submit', async (e) => {
    e.preventDefault();

    responseEl.innerHTML = '';
    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.classList.add('loading');
    }

    // ── Client-side validation ──────────────────────────────────────────────
    const minNameWords    = nameInput    ? (parseInt(nameInput.getAttribute('data-min-words'))    || 2) : 2;
    const minSubjectWords = subjectInput ? (parseInt(subjectInput.getAttribute('data-min-words')) || 3) : 3;
    const minMessageWords = messageInput ? (parseInt(messageInput.getAttribute('data-min-words')) || 5) : 5;

    let isValid = true;
    if (nameInput    && !validateTextField(nameInput,    'text',  nameInput.maxLength    || 100,  minNameWords))    isValid = false;
    if (subjectInput && !validateTextField(subjectInput, 'text',  subjectInput.maxLength || 150,  minSubjectWords)) isValid = false;
    if (messageInput && !validateTextField(messageInput, 'text',  messageInput.maxLength || 1000, minMessageWords)) isValid = false;
    if (emailInput   && !validateTextField(emailInput,   'email', 254))                                            isValid = false;
    if (phoneInput   && !validateTextField(phoneInput,   'phone', 20))                                             isValid = false;

    if (!isValid) {
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.classList.remove('loading');
      }
      const firstError = form.querySelector('.cin-error[style*="block"]');
      if (firstError) firstError.scrollIntoView({ behavior: 'smooth', block: 'center' });
      return;
    }
    // ── End validation ──────────────────────────────────────────────────────

    try {
      let token = '';
      if (window.contactin?.recaptcha && window.contactin.recaptcha.enabled && window.grecaptcha) {
        token = await grecaptcha.execute(window.contactin.recaptcha.site_key, { action: 'submit_contact' });
      }


      const formData = new FormData(form);
      // Always include the action parameter for WP AJAX
      formData.append('action', 'contactin_submit');
      if (token) formData.append('g-recaptcha-response', token);
      formData.append('nonce', window.contactin?.nonce || '');

      const res = await fetch(window.contactin?.ajaxurl || '/wp-admin/admin-ajax.php?action=contactin_submit', {
        method: 'POST',
        body: formData,
        credentials: 'same-origin'
      });

      const data = await res.json();

      if (data.success && data.data && data.data.html) {
        responseEl.innerHTML = data.data.html;
        form.remove();
        responseEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        const successWrapper = responseEl.querySelector('.contactin-success');
        if (successWrapper) {
          successWrapper.style.removeProperty('display');
          successWrapper.style.visibility = 'visible';
          successWrapper.style.opacity = '1';
          if (data.data.confetti && typeof confetti !== 'undefined') {
            confetti({ particleCount: 100, spread: 70, origin: { y: 0.6 } });
          }
        }
      } else if (!data.success && data.data && data.data.html) {
        // Show error in modal overlay instead of replacing content
        const errorModal = document.getElementById('cin-error-modal');
        const errorModalBody = document.getElementById('cin-error-modal-body');
        
        if (errorModal && errorModalBody) {
          errorModalBody.innerHTML = data.data.html;
          errorModal.classList.remove('cin-hidden');
          
          // Setup modal close handlers
          const closeBtn = errorModal.querySelector('.cin-error-modal-close');
          const retryBtn = errorModal.querySelector('[data-action="close-error-modal"]');
          const backdrop = errorModal.querySelector('.cin-error-modal-backdrop');
          
          const closeModal = () => {
            errorModal.classList.add('cin-hidden');
            // Focus back to form for accessibility
            form.scrollIntoView({ behavior: 'smooth', block: 'start' });
            submitBtn?.focus();
          };
          
          if (closeBtn) {
            closeBtn.addEventListener('click', closeModal, { once: true });
          }
          if (retryBtn) {
            retryBtn.addEventListener('click', closeModal, { once: true });
          }
          if (backdrop) {
            backdrop.addEventListener('click', closeModal, { once: true });
          }
          
          // Close on Escape key
          const handleEscape = (e) => {
            if (e.key === 'Escape') {
              closeModal();
              document.removeEventListener('keydown', handleEscape);
            }
          };
          document.addEventListener('keydown', handleEscape);
          
          // Focus management - focus on close button for accessibility
          closeBtn?.focus();
        } else {
          // Fallback if modal not found
          responseEl.innerHTML = data.data.html;
          responseEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      } else {
        responseEl.innerHTML = '<p class="cin-error">An unexpected error occurred. Please try again.</p>';
        responseEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    } catch (err) {
      console.error('[ContactIN] Submission error:', err);
      responseEl.innerHTML = '<p class="cin-error">Network error. Please check your connection and try again.</p>';
      responseEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
    } finally {
      if (submitBtn) {
        submitBtn.disabled = false;
        submitBtn.classList.remove('loading');
      }
    }
  });

  // ========================================
  // Name field: real-time counter + validation
  // ========================================
  if (nameInput) {
    const minNameWords = parseInt(nameInput.getAttribute('data-min-words')) || 2;
    nameInput.addEventListener('input', () => {
      updateCharCounter(nameInput);
      validateFieldRealTime(nameInput, 'text', nameInput.maxLength || 100);
    });
    nameInput.addEventListener('blur', () => validateTextField(nameInput, 'text', nameInput.maxLength || 100, minNameWords));
    // Initialize counter on load
    updateCharCounter(nameInput);
  }

  // ========================================
  // Subject field: real-time counter + validation
  // ========================================
  if (subjectInput) {
    const minSubjectWords = parseInt(subjectInput.getAttribute('data-min-words')) || 3;
    subjectInput.addEventListener('input', () => {
      updateCharCounter(subjectInput);
      validateFieldRealTime(subjectInput, 'text', subjectInput.maxLength || 150);
    });
    subjectInput.addEventListener('blur', () => validateTextField(subjectInput, 'text', subjectInput.maxLength || 150, minSubjectWords));
    // Initialize counter on load
    updateCharCounter(subjectInput);
  }

  // ========================================
  // Message field: real-time counter + validation
  // ========================================
  if (messageInput) {
    const minMessageWords = parseInt(messageInput.getAttribute('data-min-words')) || 5;
    messageInput.addEventListener('input', () => {
      updateCharCounter(messageInput);
      validateFieldRealTime(messageInput, 'text', messageInput.maxLength || 1000);
    });
    messageInput.addEventListener('blur', () => validateTextField(messageInput, 'text', messageInput.maxLength || 1000, minMessageWords));
    // Initialize counter on load
    updateCharCounter(messageInput);
  }

  // ========================================
  // Email field: real-time validation
  // ========================================
  if (emailInput) {
    emailInput.addEventListener('input', () => validateFieldRealTime(emailInput, 'email', 254));
    emailInput.addEventListener('blur', () => validateTextField(emailInput, 'email', 254));
  }

  // ========================================
  // Phone field: real-time validation
  // ========================================
  if (phoneInput) {
    phoneInput.addEventListener('input', () => validateFieldRealTime(phoneInput, 'phone', 20));
    phoneInput.addEventListener('blur', () => validateTextField(phoneInput, 'phone', 20));
  }

  const matchesAllowedExt = (ext) => {
    if (!ext) return false;
    return allowedExtKeys.some(key => key.split('|').includes(ext));
  };

  // ========================================
  // File input: real-time validation
  // ========================================
  if (fileInput) {
    fileInput.addEventListener('change', () => {
      showError(fileInput, '');
      const file = fileInput.files[0];
      if (!file) return; // do nothing if no file selected

      const name = String(file.name || '');
      const parts = name.split('.');
      const ext = parts.length > 1 ? parts.pop().toLowerCase() : '';

      // Check file type
      if (ext && !matchesAllowedExt(ext)) {
        const allowedList = allowedExtKeys.join(', ');
        showError(fileInput, `File type .${ext} is not allowed. Allowed types: ${allowedList}`);
        fileInput.value = '';
        return;
      }

      // Check file size
      if (maxFileSize > 0 && file.size > maxFileSize * 1024 * 1024) {
        showError(fileInput, `File size ${(file.size / 1024 / 1024).toFixed(2)} MB exceeds maximum of ${maxFileSize} MB.`);
        fileInput.value = '';
        return;
      }

      // Show file info if validation passes
      const fileSizeMB = (file.size / 1024 / 1024).toFixed(2);
      const fieldMeta = fileInput.parentNode.querySelector('.cin-field-meta');
      if (fieldMeta) {
        const fileInfo = fieldMeta.querySelector('.cin-file-info');
        if (fileInfo) {
          fileInfo.remove();
        }
        const info = document.createElement('div');
        info.className = 'cin-file-info';
        info.style.color = '#46b450';
        info.style.fontSize = '13px';
        info.style.marginTop = '8px';
        info.textContent = `✓ File: ${name} (${fileSizeMB} MB)`;
        fieldMeta.appendChild(info);
      }
    });

    // Also validate on blur (for cases where user selects and then blurs without selecting)
    fileInput.addEventListener('blur', () => {
      if (!fileInput.files.length) {
        showError(fileInput, '');
        const fieldMeta = fileInput.parentNode.querySelector('.cin-field-meta');
        if (fieldMeta) {
          const fileInfo = fieldMeta.querySelector('.cin-file-info');
          if (fileInfo) fileInfo.remove();
        }
      }
    });
  }


  // Existing submit logic preserved
  // ...existing code...
});

// Error display helper
function showError(input, error) {
  let errorEl = input.parentNode.querySelector('.cin-error');
  if (!errorEl) {
    errorEl = document.createElement('div');
    errorEl.className = 'cin-error';
    errorEl.style.color = '#d63638';
    errorEl.style.fontSize = '13px';
    errorEl.style.marginTop = '6px';
    input.parentNode.appendChild(errorEl);
  }
  errorEl.textContent = error;
  errorEl.style.display = error ? 'block' : 'none';
  if (error) {
    input.style.borderColor = '#d63638';
    input.style.backgroundColor = '#fff5f5';
  } else {
    input.style.borderColor = '';
    input.style.backgroundColor = '';
  }
}
